	frameCmd := &cobra.Command{Use: "frames", Aliases: []string{"frame"}, Short: "Manage frames catalog entries"}
	frameListCmd := &cobra.Command{
		Use:   "list",
		Short: "List frames in the catalog",
		RunE: func(cmd *cobra.Command, args []string) error {
			filter, _ := cmd.Flags().GetString("filter")
			columns, _ := cmd.Flags().GetStringSlice("column")
			sortOpts, _ := cmd.Flags().GetStringSlice("sort")
			limit, _ := cmd.Flags().GetInt32("limit")
			includeArchived, _ := cmd.Flags().GetBool("include-archived")
			if limit < 0 {
				cmd.SilenceUsage = false
				return fmt.Errorf("limit cannot be negative")
			}
			client := opsconnect.NewFrameOpsServiceClient(getOpsHTTPClient(), getOpsServerURL())
			var all []*apipb.Frame
			var currentToken string
			for {
				pageSize := int32(100)
				if limit > 0 {
					remaining := limit - int32(len(all))
					if remaining <= 0 {
						break
					}
					if remaining < pageSize {
						pageSize = remaining
					}
				}
				req := &pb.ListFramesOpsRequest{Filter: filter, Columns: columns, Sort: sortOpts, PageSize: pageSize, PageToken: currentToken, IncludeArchived: includeArchived}
				res, err := client.ListFrames(cmd.Context(), connect.NewRequest(req))
				if err != nil {
					return err
				}
				all = append(all, res.Msg.Frames...)
				if limit > 0 && int32(len(all)) >= limit {
					all = all[:limit]
					break
				}
				if res.Msg.NextPageToken == "" {
					break
				}
				currentToken = res.Msg.NextPageToken
			}
			if len(columns) == 0 {
				columns = getDefaultColumns(&apipb.Frame{})
				if includeArchived && len(columns) > 0 {
					columns = append(columns, "is_archived")
				}
			}
			yamlOut, _ = cmd.Flags().GetBool("yaml")
			return printCatalogListOutput(cmd.OutOrStdout(), all, columns)
		},
	}
	frameListCmd.Flags().BoolVar(&yamlOut, "yaml", false, "Output format as YAML")
	frameListCmd.Flags().StringP("filter", "f", "", "CEL filter string")
	frameListCmd.Flags().Int32P("limit", "l", 0, "Maximum number of items to return")
	frameListCmd.Flags().StringSliceP("column", "c", nil, "Columns to select")
	frameListCmd.Flags().StringSliceP("sort", "s", nil, "Columns to sort by (e.g. ^name)")
	frameListCmd.Flags().Bool("include-archived", false, "Include archived/delisted components in results")
	_ = frameListCmd.RegisterFlagCompletionFunc("filter", func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
		cols := getColumns(&apipb.Frame{})
		re := regexp.MustCompile(`([a-zA-Z_]+)$`)
		match := re.FindStringSubmatch(toComplete)
		prefix := ""
		base := toComplete
		if len(match) > 0 {
			prefix = match[1]
			base = toComplete[:len(toComplete)-len(prefix)]
		}
		var filtered []string
		for _, c := range cols {
			if len(prefix) == 0 || strings.HasPrefix(c, prefix) {
				filtered = append(filtered, base+c)
			}
		}
		return filtered, cobra.ShellCompDirectiveNoFileComp
	})
	frameCmd.AddCommand(frameListCmd)

